-- QA DESCO APAPPSS / Materia seca del fundo.\n-- Datos existentes: uotId=2, convenioId=2, predioId=10032.\n-- Lecturas sin cambio persistente; alta de prueba solo bajo transaccion ROLLBACK.\nSET NOCOUNT ON;\n\nDECLARE @uot BIGINT=2, @conv BIGINT=2, @predio BIGINT=10032, @usuario BIGINT=1;\nDECLARE @ahora DATETIME2(0)=SYSUTCDATETIME();\n\n-- 1) Verificar base del ambito, permisos efectivos y modulos especiales.\nSELECT 'AMBITO' control,A.predio_id,A.uot_id,A.convenio_uot_organizacion_id\nFROM prod.PredioAmbito A\nJOIN org.ConvenioUOTOrganizacion C ON C.convenio_uot_organizacion_id=A.convenio_uot_organizacion_id\nJOIN org.ConvenioModuloEspecial CM ON CM.convenio_uot_organizacion_id=C.convenio_uot_organizacion_id AND CM.estado=1\nJOIN seg.ModuloEspecial ME ON ME.modulo_especial_id=CM.modulo_especial_id AND ME.codigo='COMERCIALIZACION_ASOCIATIVA' AND ME.estado=1\nWHERE A.predio_id=@predio AND A.uot_id=@uot AND A.convenio_uot_organizacion_id=@conv AND A.estado=1 AND C.estado=1;\n\nSELECT 'PERMISOS' control,P.codigo,\n seg.FN_Usuario_TienePermisoUOT(@usuario,@uot,P.codigo) permiso_efectivo\nFROM seg.Permiso P\nWHERE P.codigo IN ('APAPPSS_PREDIOS_VER','APAPPSS_PREDIOS_EDITAR','APAPPSS_PREDIOS_SECA_LOTE',\n'APAPPSS_PREDIOS_SECA_EDITAR','APAPPSS_PREDIOS_SECA_ELIMINAR')\nORDER BY P.codigo;\n\n-- 2) Usar solo una sesion REAL, activa, del administrador. Nunca inventar sesion.\nDECLARE @sesion UNIQUEIDENTIFIER;\nSELECT TOP(1) @sesion=S.sesion_publica_id\nFROM seg.SesionUsuario S\nJOIN seg.Usuario U ON U.usuario_id=S.usuario_id AND U.estado=1 AND U.estado_cuenta='ACTIVA'\nWHERE S.usuario_id=@usuario AND S.estado=1 AND S.fecha_revocacion IS NULL\n AND S.fecha_expiracion_renovacion>@ahora AND S.token_version=U.token_version\n AND (S.modo_uot='GENERAL' OR S.modo_uot='ESPECIFICA' AND S.uot_contexto_id=@uot)\nORDER BY S.fecha_ultima_actividad DESC,S.sesion_usuario_id DESC;\nIF @sesion IS NULL\nBEGIN\n PRINT N'QA PARCIAL: inicie sesion como administrador en UOT 2 y repita las pruebas de GET/POST.';\n RETURN;\nEND;\n\nDECLARE @corr UNIQUEIDENTIFIER=NEWID(), @sol UNIQUEIDENTIFIER=NEWID();\nDECLARE @filtros NVARCHAR(MAX)=\n (SELECT @uot uotId,@conv convenioId,@predio predioId FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);\nDECLARE @contexto NVARCHAR(MAX)=\n (SELECT @sesion sesionPublicaId,@corr correlacionId,@sol solicitudId,\n  N'/api/v1/apappss/predios/10032/materia-seca' endpoint\n  FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);\nDECLARE @peticion NVARCHAR(MAX)=\n (SELECT JSON_QUERY(@contexto) contexto,JSON_QUERY(@filtros) filtros,\n JSON_QUERY(N'{}') datos FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);\nDECLARE @uid BIGINT,@sid BIGINT,@did BIGINT,@eid BIGINT,@mid INT,\n @oc UNIQUEIDENTIFIER,@os UNIQUEIDENTIFIER,@ip VARCHAR(64),@endpoint NVARCHAR(250),\n @ok BIT,@msg NVARCHAR(300),@code VARCHAR(60),@http SMALLINT, @datos NVARCHAR(MAX);\n\nEXEC seg.PA_Operacion_Sel_ContextoAutorizado\n @cJson=@peticion,@cCodigoPermiso='APAPPSS_PREDIOS_VER',\n @nUsuarioId=@uid OUTPUT,@nSesionUsuarioId=@sid OUTPUT,\n @nDispositivoUsuarioId=@did OUTPUT,@nEmpleadoId=@eid OUTPUT,@nModuloId=@mid OUTPUT,\n @gCorrelacionId=@oc OUTPUT,@gSolicitudId=@os OUTPUT,@cIp=@ip OUTPUT,\n @cEndpoint=@endpoint OUTPUT,@bResultado=@ok OUTPUT,@cMensaje=@msg OUTPUT,\n @cCodigoRespuesta=@code OUTPUT,@nHttpRespuesta=@http OUTPUT;\nSELECT 'CONTEXTO_VER' control,@ok exitoso,@code codigo,@http http,@msg mensaje;\nIF ISNULL(@ok,0)<>1 RETURN;\n\nEXEC prod.PA_E3_ExpedienteE4_Ejecutar @cAccion='SECA_PREDIO_LISTAR',@cJson=@peticion,\n @cDatos=@datos OUTPUT,@bResultado=@ok OUTPUT,@cMensaje=@msg OUTPUT,\n @cCodigoRespuesta=@code OUTPUT,@nHttpRespuesta=@http OUTPUT;\nSELECT 'LISTAR_SECA' control,@ok exitoso,@code codigo,@http http,@msg mensaje,\n TRY_CONVERT(INT,JSON_VALUE(@datos,'$.totalPlantasActivas')) plantas_activas,\n (SELECT COUNT(*) FROM OPENJSON(@datos,'$.items')) registros;\nIF ISNULL(@ok,0)<>1 RETURN;\n\n-- 3) Registrar una muestra ficticia dentro de una transaccion que se revierte.\n-- Omitir alta si ya existe otra muestra en la ventana semanal.\nIF EXISTS(SELECT 1 FROM prod.PredioMateriaSecaGlobalE4\n WHERE predio_id=@predio AND uot_id=@uot AND convenio_id=@conv AND estado=1\n AND ABS(DATEDIFF(DAY,fecha_muestreo,CONVERT(DATE,@ahora)))<7)\nBEGIN\n PRINT N'QA ALTA OMITIDA: hay un muestreo activo en la ventana de 7 dias.';\n RETURN;\nEND;\nIF NOT EXISTS(SELECT 1 FROM prod.PlantaPaltaE3\n WHERE predio_id=@predio AND uot_id=@uot AND convenio_id=@conv AND activo=1\n AND estado_actual NOT IN ('MUERTA','ELIMINADA'))\nBEGIN\n PRINT N'QA ALTA OMITIDA: el fundo no tiene plantas activas.';\n RETURN;\nEND;\n\nDECLARE @clave UNIQUEIDENTIFIER=NEWID(), @muestra NVARCHAR(MAX);\nSET @contexto=(SELECT @sesion sesionPublicaId,@corr correlacionId,@sol solicitudId,\n @clave claveIdempotencia,N'/api/v1/apappss/predios/10032/materia-seca' endpoint\n FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);\nSET @muestra=(SELECT CONVERT(DECIMAL(6,3),21.500) porcentaje,1 cantidadPlantas,\n 3 cantidadFrutos,'LABORATORIO' metodo,CONVERT(DATE,@ahora) fechaMuestreo,\n N'Prueba transaccional de registro de materia seca.' informe\n FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);\nSET @peticion=(SELECT JSON_QUERY(@contexto) contexto,JSON_QUERY(@filtros) filtros,\n JSON_QUERY(@muestra) datos FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);\n\nBEGIN TRY\n BEGIN TRANSACTION;\n EXEC prod.PA_E3_ExpedienteE4_Ejecutar @cAccion='SECA_GLOBAL',@cJson=@peticion,\n  @cDatos=@datos OUTPUT,@bResultado=@ok OUTPUT,@cMensaje=@msg OUTPUT,\n  @cCodigoRespuesta=@code OUTPUT,@nHttpRespuesta=@http OUTPUT;\n SELECT 'REGISTRAR_SECA_QA' control,@ok exitoso,@code codigo,@http http,@msg mensaje,\n  TRY_CONVERT(BIGINT,JSON_VALUE(@datos,'$.informeId')) informe_qa;\n IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;\n SELECT 'ROLLBACK' control,'SIN CAMBIOS PERSISTENTES' resultado;\nEND TRY\nBEGIN CATCH\n IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;\n SELECT 'REGISTRAR_SECA_QA' control,0 exitoso,ERROR_NUMBER() error_sql,\n  N'Prueba revertida. Consultar el registro del servidor.' resultado;\nEND CATCH;\n
